from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/headers")
async def read_headers(my_header: str = Header(None, alias="my_header", convert_underscores=True)):
    return {"my_header": my_header}

client = TestClient(app)

def test_alias_with_underscore():
    # This should NOT work if convert_underscores=True, even if alias is provided with underscore
    resp = client.get("/headers", headers={"my_header": "foo"})
    print(f"Alias underscore, convert True: {resp.json()}")
    # If the bug exists, this will be {'my_header': 'foo'}
    # If fixed, it should be {'my_header': None}

if __name__ == "__main__":
    test_alias_with_underscore()
